(()=>{const root=document.documentElement,button=document.querySelector('.theme-toggle');function update(){const dark=root.dataset.theme==='dark';button.textContent=dark?'Light mode':'Dark mode';button.setAttribute('aria-pressed',String(dark));button.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');document.querySelector('meta[name="theme-color"]').content=dark?'#343638':'#f0ef39';}button.addEventListener('click',()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('yardthreads-theme',root.dataset.theme)}catch{}update()});window.addEventListener('storage',e=>{if(e.key==='yardthreads-theme'){root.dataset.theme=e.newValue==='dark'?'dark':'light';update()}});update()})();